package com.example.starter.blast.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;

import java.math.BigDecimal;
import java.time.Instant;

/**
 * 爆破作业申请请求体。
 *
 * @param requestId        幂等键
 * @param mineCode         矿区编码
 * @param zoneCode         爆区编码
 * @param applicant        申请人
 * @param plannedTime      计划起爆时刻，UTC（例如 2026-09-26T02:00:00Z）
 * @param chargePerDelayKg 单段药量，单位 kg，必须为正数
 */
public record ApplyRequest(
        @NotBlank String requestId,
        @NotBlank String mineCode,
        @NotBlank String zoneCode,
        @NotBlank String applicant,
        @NotNull Instant plannedTime,
        @NotNull @Positive BigDecimal chargePerDelayKg) {
}

package com.example.starter.blast.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

import java.time.Instant;

/**
 * 起爆备案请求体。
 *
 * @param requestId      幂等键
 * @param applicationId  已审批通过的作业申请 ID
 * @param detonateTime   实际起爆时刻，UTC
 */
public record FilingRequest(
        @NotBlank String requestId,
        @NotNull Long applicationId,
        @NotNull Instant detonateTime) {
}

package com.example.starter.blast.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.PositiveOrZero;

import java.math.BigDecimal;
import java.time.Instant;

/**
 * 振动监测读数回传请求体。
 * 去重自然键为：爆区＋测点＋采样时刻。
 *
 * @param applicationId 读数归属的已备案作业 ID
 * @param zoneCode      爆区编码
 * @param pointCode     测点编码
 * @param sampleTime    采样时刻，UTC
 * @param velocityMmS   质点振动速度峰值，单位 mm/s
 */
public record VibrationReadingRequest(
        @NotNull Long applicationId,
        @NotBlank String zoneCode,
        @NotBlank String pointCode,
        @NotNull Instant sampleTime,
        @NotNull @PositiveOrZero BigDecimal velocityMmS) {
}

package com.example.starter.blast.api;

import jakarta.validation.constraints.AssertTrue;
import jakarta.validation.constraints.NotBlank;

/**
 * 监管复核解冻请求体。
 *
 * @param requestId 幂等键
 * @param reviewer  复核人
 * @param confirmed 必须为 true 表示监管复核确认解除冻结
 */
public record UnfreezeReviewRequest(
        @NotBlank String requestId,
        @NotBlank String reviewer,
        @AssertTrue Boolean confirmed) {
}

package com.example.starter.blast.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * 效果评估封档请求体。
 *
 * @param requestId   幂等键
 * @param applicationId 已完成振动回传的作业 ID
 * @param evaluator   评估人
 * @param conclusion  评估结论
 */
public record EvaluationRequest(
        @NotBlank String requestId,
        @NotNull Long applicationId,
        @NotBlank String evaluator,
        @NotBlank String conclusion) {
}

