package com.example.starter.blast.domain;

import java.math.BigDecimal;

/**
 * 爆区备案持久化对象。
 *
 * @param maxChargePerDelayKg 备案单段最大药量，单位 kg
 */
public record BlastZone(
        String zoneCode,
        String mineCode,
        String zoneName,
        BigDecimal maxChargePerDelayKg) {
}

package com.example.starter.blast.domain;

import java.math.BigDecimal;

/**
 * 监测测点备案持久化对象。
 *
 * @param velocityLimitMmS 质点振速阈值，单位 mm/s
 */
public record MonitoringPoint(
        String zoneCode,
        String pointCode,
        String pointName,
        BigDecimal velocityLimitMmS) {
}

package com.example.starter.blast.domain;

import java.math.BigDecimal;
import java.time.Instant;

/**
 * 爆破作业申请持久化对象。
 *
 * @param detonateTime 实际起爆备案时刻（UTC），未备案为 NULL
 * @param rejectReason 驳回/作废原因，NULL 表示无
 */
public record BlastApplication(
        Long id,
        String mineCode,
        String zoneCode,
        String applicant,
        Instant plannedTime,
        BigDecimal chargePerDelayKg,
        ApplicationStatus status,
        Instant detonateTime,
        String rejectReason,
        Instant createdAt,
        Instant updatedAt) {

    public BlastApplication withStatus(ApplicationStatus newStatus, String reason, Instant detonateTime, Instant now) {
        return new BlastApplication(id, mineCode, zoneCode, applicant, plannedTime, chargePerDelayKg,
                newStatus, detonateTime, reason, createdAt, now);
    }
}

package com.example.starter.blast.domain;

import java.math.BigDecimal;
import java.time.Instant;

/**
 * 振动读数持久化对象。
 *
 * @param overLimit 是否超过测点备案振速阈值
 */
public record VibrationReading(
        Long id,
        Long applicationId,
        String zoneCode,
        String pointCode,
        Instant sampleTime,
        BigDecimal velocityMmS,
        boolean overLimit,
        Instant createdAt) {
}

package com.example.starter.blast.domain;

import java.time.Instant;

/**
 * 效果评估封档持久化对象。
 */
public record EffectEvaluation(
        Long id,
        Long applicationId,
        String requestId,
        String evaluator,
        String conclusion,
        Instant archivedAt) {
}

