    void sameKeyDifferentParamsConflictsAndKeepsState() {
        var first = post("/api/blast/applications", new ApplyBody(
                "idem-apply-2", MINE, "ZONE-A", "申请人甲",
                PLANNED.toString(), new BigDecimal("200.000")));
